cat >> ledger/errors.py <<'EOF'


class UnknownFormatError(StatementError):
    """Формат или кодировка выписки не распознаны (или не подходят к заданному fmt)."""


class StatementRowError(StatementError):
    """Строка выписки не разобрана в строгом режиме; line_no заполнен всегда."""
EOF
cat > ledger/importer.py <<'EOF'
"""Импорт банковских выписок.

Поддерживаются форматы (колонки ищутся по названию без учёта регистра и
пробелов по краям, в любом порядке, лишние колонки игнорируются):

    nova         date,amount,description               (разделитель ",")
    sfera        Дата;Сумма;Описание                    (разделитель ";")
    sfera_split  Дата;Описание;Приход;Расход            (разделитель ";")

Кодировка — UTF-8 (BOM допустим), иначе cp1251.
"""

from __future__ import annotations

import csv
import datetime as dt
import io
import logging
import os
import re
from collections import Counter
from dataclasses import dataclass, field
from decimal import Decimal
from typing import Callable

from ledger.clock import Clock, SystemClock
from ledger.errors import (
    StatementError,
    StatementRowError,
    UnknownFormatError,
    ValidationError,
)
from ledger.models import Transaction, parse_amount, to_money
from ledger.rules import Categorizer, normalize_text
from ledger.storage import MemoryStore

logger = logging.getLogger(__name__)

NOVA_COLUMNS = ("date", "amount", "description")

_SFERA_DATE = re.compile(r"^[0-9]{2}\.[0-9]{2}\.[0-9]{4}$")
_SFERA_AMOUNT = re.compile(r"^[+-]?(?:[0-9]{1,3}(?:[  ][0-9]{3})+|[0-9]+)(?:,[0-9]{1,2})?$")


@dataclass(frozen=True)
class RowError:
    """Ошибка разбора одной строки выписки (line_no — физическая строка файла)."""

    line_no: int
    message: str


@dataclass(frozen=True)
class ImportResult:
    """Итог импорта выписки."""

    format: str
    encoding: str
    added: int
    duplicates: int
    errors: list[RowError] = field(default_factory=list)


def normalize_description(text: str) -> str:
    """Сравнение описаний для дедупликации (то же, что rules.normalize_text)."""
    return normalize_text(text)


# --- разбор значений ---------------------------------------------------------


def _parse_sfera_date(text: str) -> dt.date:
    value = text.strip()
    if not _SFERA_DATE.match(value):
        raise ValidationError(f"invalid date {text!r}")
    try:
        return dt.date(int(value[6:]), int(value[3:5]), int(value[:2]))
    except ValueError as exc:
        raise ValidationError(f"invalid date {text!r}") from exc


def _parse_sfera_amount(text: str) -> Decimal:
    value = text.strip()
    if not _SFERA_AMOUNT.match(value):
        raise ValidationError(f"invalid amount: {text!r}")
    normalized = value.replace(" ", "").replace(" ", "").replace(",", ".")
    return to_money(Decimal(normalized))


def _split_part(text: str, name: str) -> Decimal | None:
    """Колонка Приход/Расход: None для пустой или нулевой, иначе положительная сумма."""
    value = text.strip()
    if not value:
        return None
    if value[0] in "+-":
        raise ValidationError(f"{name} must not have a sign: {text!r}")
    amount = _parse_sfera_amount(value)
    return amount if amount != 0 else None


# Каждая функция получает ячейки по именам колонок и отдаёт (date, amount, description).
Cells = dict[str, str]
Builder = Callable[[Cells], tuple[dt.date, Decimal, str]]


def _build_nova(c: Cells) -> tuple[dt.date, Decimal, str]:
    try:
        date = dt.date.fromisoformat(c["date"].strip())
    except ValueError as exc:
        raise ValidationError(f"invalid date {c['date']!r}") from exc
    return date, parse_amount(c["amount"]), c["description"]


def _build_sfera(c: Cells) -> tuple[dt.date, Decimal, str]:
    return _parse_sfera_date(c["дата"]), _parse_sfera_amount(c["сумма"]), c["описание"]


def _build_sfera_split(c: Cells) -> tuple[dt.date, Decimal, str]:
    date = _parse_sfera_date(c["дата"])
    income = _split_part(c["приход"], "income")
    expense = _split_part(c["расход"], "expense")
    if income is not None and expense is not None:
        raise ValidationError("both income and expense are filled")
    if income is None and expense is None:
        raise ValidationError("neither income nor expense is filled")
    amount = income if income is not None else -expense  # type: ignore[operator]
    return date, amount, c["описание"]


@dataclass(frozen=True)
