    columns: tuple[str, ...]
    build: Builder


_FORMATS = {
    f.name: f
    for f in (
        _Format("nova", ",", NOVA_COLUMNS, _build_nova),
        _Format("sfera", ";", ("дата", "сумма", "описание"), _build_sfera),
        _Format("sfera_split", ";", ("дата", "описание", "приход", "расход"), _build_sfera_split),
    )
}


# --- чтение файла ------------------------------------------------------------


def _read_text(path: str | os.PathLike[str]) -> tuple[str, str]:
    with open(path, "rb") as fh:
        data = fh.read()
    try:
        return data.decode("utf-8-sig"), "utf-8"
    except UnicodeDecodeError:
        pass
    try:
        return data.decode("cp1251"), "cp1251"
    except UnicodeDecodeError as exc:
        raise UnknownFormatError("file is neither UTF-8 nor cp1251") from exc


def _is_junk(row: list[str]) -> bool:
    return all(not cell.strip() for cell in row)


def _is_header_junk(row: list[str]) -> bool:
    return all(not cell.strip().strip(",;").strip() for cell in row)


class _Rows:
    """Читает записи CSV, помня физический номер строки начала записи."""

    def __init__(self, text: str, delimiter: str) -> None:
        self._reader = csv.reader(io.StringIO(text, newline=""), delimiter=delimiter)

    def next(self) -> tuple[int, list[str] | csv.Error] | None:
        before = self._reader.line_num
        try:
            row = next(self._reader)
        except StopIteration:
            return None
        except csv.Error as exc:
            if self._reader.line_num == before:
                return None
            return before + 1, exc
        return before + 1, row


def _find_header(rows: _Rows) -> tuple[int, list[str] | csv.Error] | None:
    while True:
        item = rows.next()
        if item is None:
            return None
        row = item[1]
        if isinstance(row, csv.Error) or not _is_header_junk(row):
            return item


def _header_map(fmt: _Format, row: list[str] | csv.Error) -> dict[str, int] | None:
    """Имя колонки -> индекс, если заголовок подходит формату."""
    if isinstance(row, csv.Error):
        return None
    names = [cell.strip().casefold() for cell in row]
    mapping = {}
    for col in fmt.columns:
        if names.count(col) != 1:
            return None
        mapping[col] = names.index(col)
    return mapping


def _open_statement(
    path: str | os.PathLike[str], fmt: str | None
) -> tuple[_Format, str, _Rows, dict[str, int]]:
    if fmt is not None and fmt not in _FORMATS:
        raise UnknownFormatError(f"unknown format {fmt!r}")
    text, encoding = _read_text(path)
    candidates = [_FORMATS[fmt]] if fmt else list(_FORMATS.values())
    matches = []
    first_line: int | None = None
    for candidate in candidates:
        rows = _Rows(text, candidate.delimiter)
        header = _find_header(rows)
        if header is None:
            continue
        if first_line is None:
            first_line = header[0]
        mapping = _header_map(candidate, header[1])
        if mapping is not None:
            matches.append((candidate, rows, mapping))
    if not matches:
        if first_line is None:
            raise UnknownFormatError("empty statement: no header found")
        wanted = f" for format {fmt!r}" if fmt else ""
        raise UnknownFormatError(f"unrecognized header{wanted}", line_no=first_line)
    if len(matches) > 1:
        raise UnknownFormatError("ambiguous header", line_no=first_line)
    chosen, rows, mapping = matches[0]
    return chosen, encoding, rows, mapping


def detect_format(path: str | os.PathLike[str]) -> str:
    """Определяет формат выписки по заголовку: "nova", "sfera" или "sfera_split"."""
    return _open_statement(path, None)[0].name


# --- импорт ------------------------------------------------------------------


def import_statement(
    path: str | os.PathLike[str],
    store: MemoryStore,
    *,
    fmt: str | None = None,
    strict: bool = False,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> ImportResult:
    """Импортирует выписку в store: сначала разбирает весь файл, затем пишет одной пачкой.

    Дубли (дата, сумма, normalize_description с учётом количества) относительно
    содержимого store до импорта пропускаются. Ошибочные строки попадают в
    ImportResult.errors, а при strict=True первая из них даёт StatementRowError,
    и ничего не записывается.
    """
    clock = clock or SystemClock()
    spec, encoding, rows, mapping = _open_statement(path, fmt)
    width = max(mapping.values()) + 1

    existing = Counter(
        (tx.date, tx.amount, normalize_description(tx.description)) for tx in store.all()
    )
    imported_at = clock.now()
    new: list[Transaction] = []
    errors: list[RowError] = []
    duplicates = 0

    while True:
        item = rows.next()
        if item is None:
            break
        line_no, row = item
        if isinstance(row, csv.Error):
            message = str(row)
        elif _is_junk(row):
            continue
        elif len(row) < width:
            message = "not enough fields"
        else:
            try:
                cells = {col: row[idx] for col, idx in mapping.items()}
                date, amount, description = spec.build(cells)
                tx = Transaction(
                    date=date,
                    amount=amount,
                    description=description.strip(),
                    imported_at=imported_at,
                )
            except (ValidationError, ValueError) as exc:
                message = str(exc)
            else:
                key = (tx.date, tx.amount, normalize_description(tx.description))
                if existing[key] > 0:
                    existing[key] -= 1
                    duplicates += 1
                    continue
                if categorizer is not None:
                    category = categorizer.categorize(tx)
                    if category is not None:
                        tx = Transaction(
                            date=tx.date,
                            amount=tx.amount,
                            description=tx.description,
                            category=category,
                            imported_at=tx.imported_at,
                        )
                new.append(tx)
                continue
        if strict:
            raise StatementRowError(message, line_no=line_no)
        errors.append(RowError(line_no, message))

    if new:
        store.add_many(new)
    logger.info(
        "imported %d transactions from %s (%d duplicates, %d errors)",
        len(new), path, duplicates, len(errors),
    )
    return ImportResult(
        format=spec.name,
        encoding=encoding,
        added=len(new),
        duplicates=duplicates,
        errors=errors,
    )


def import_csv(
    path: str | os.PathLike[str],
    store: MemoryStore,
    categorizer: Categorizer | None = None,
    clock: Clock | None = None,
) -> int:
    """Строго импортирует выписку «Новы» в store и возвращает число добавленных транзакций."""
    result = import_statement(
        path, store, fmt="nova", strict=True, categorizer=categorizer, clock=clock
    )
    return result.added
